Definition VT_STACK : Z := 144.

Definition vtc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (v f np vp : Z) (name value : list byte) (tl lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' pad tail,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (v, v + 12 + zlength name + zlength value + tl)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' v (ValCells (mkElt f name value pad tail)) /\ zlength tail = tl
    /\ bytes_at usegs m' np name /\ bytes_at usegs m' vp value.

Definition vtc_stmt : Prop := forall (v f np vp : Z) (name value : list byte) (tl lo : Z) (n : nat) (junk : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m v [CB n junk] -> Z.of_nat n = 12 + zlength name + zlength value + tl -> 0 <= tl ->
  bytes_at usegs m np name -> bytes_at usegs m vp value ->
  zlength name + 2 < 2^16 -> zlength value < 2^16 -> 0 <= f < 2^16 ->
  (np + zlength name <= v \/ v + Z.of_nat n <= np) -> (vp + zlength value <= v \/ v + Z.of_nat n <= vp) ->
  v + Z.of_nat n <= lo ->
  (np + zlength name <= lo \/ bv_unsigned sp <= np) -> (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  stk usegs m lo (bv_unsigned sp) -> lo + VT_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  v mod 8 = 0 -> 48 <= v ->
  mem_inv usegs m ->
  evt usegs (vtc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc v f np vp name value tl lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_VALUE_TYPE_CTOR) fc None m (seg_rom usegs)).
