  rewrite trimB_snoc, length_app. cbn [length]. destruct (is_ws b).
  - destruct IH as (k & K & E). exists k. split; [lia|]. rewrite firstn_app.
    replace (k - length bs)%nat with 0%nat by lia. cbn. rewrite app_nil_r. exact E.
