  Hypothesis VHI : vp + zlength value < 2^64.
  Hypothesis VNZ : 0 < zlength value -> 0 < vp.
Scheme kc__6 := Elimination for Corelib.Init.Datatypes.option Sort Prop.     (* [comment removed for export] *)

  (* [comment removed for export] *)
  Lemma tc_loopB : forall (cnt j : nat) (p : Z) (D : list byte) (a3x a4 a5 a6 a7 s6x : word),
    (cnt = j)%nat -> (1 <= j <= length D)%nat ->
    bytes_at usegs m1 p D -> vp <= p -> p + zlength D <= vp + zlength value ->
    (exists d0 D', D = d0 :: D' /\ is_ws d0 = false) ->
    trim value = trimB (firstn j D) ->
    evt usegs (tc_scan_post sp' gp tp t0 t1 t2 nl np f s4 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc vp name value m1)
      (MS (mkR rax sp' gp tp t0 t1 t2 (Z_to_bv 64 nl) (Z_to_bv 64 np)
                (Z_to_bv 64 1) (Z_to_bv 64 32) (Z_to_bv 64 9) a3x a4 a5 a6 a7
                (Z_to_bv 64 f) (Z_to_bv 64 (p + Z.of_nat j)) s4 (Z_to_bv 64 p) s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
