(* [comment removed for export] *)

(* [comment removed for export] *)
Definition tc_frame (m : mem) (sp ra s0 s1 s2 s3 s4 s5 s6 : word) (junk : list byte) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -96) [CB 32 junk; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition TC_SEG_STACK : Z := 96.

(* [comment removed for export] *)
Definition tc_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f np vp : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk p5 msk vp',
    ms' = MS (mkR (Z_to_bv 64 P_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) (Z_to_bv 64 (zlength (trim value))) s4 (Z_to_bv 64 p5) (Z_to_bv 64 msk) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -96)
    /\ tc_frame m' sp ra s0 s1 s2 s3 s4 s5 s6 junk
    /\ Z.land msk p5 = vp' /\ 0 <= p5 < 2^64 /\ 0 <= msk < 2^64
    /\ bytes_at usegs m' vp' (trim value)
    /\ ((vp <= vp' /\ vp' + zlength (trim value) <= vp + zlength value) \/ (vp' = 0 /\ trim value = [])).

Definition tc_seg1_stmt : Prop := forall (Fa f np vp ec : Z) (name value : list byte) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m vp value ->
  zlength name <= 65533 -> zlength value <= 65533 -> vp + zlength value < 2^64 ->
  (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  stk usegs m lo (bv_unsigned sp) -> lo + TC_SEG_STACK <= bv_unsigned sp -> hceil <= lo ->
  (0 < zlength value -> 0 < vp) ->                                           (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (tc_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f np vp name value lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Fa) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ec) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_NEW_ELEMENT) fc None m (seg_rom usegs)).

